import { finding } from '../../engine/checks/helpers/findings.mjs';
import { wikiPages, sectionBody, BULLET } from './lib.mjs';

// Citation discipline: every top-level bullet in a Sources section carries
// its real URL — a markdown link or a bare URL both verify; the invariant is
// reachability, not link typography. A bullet is judged over its whole
// block — the bullet line plus its indented continuation lines — so a
// hard-wrapped source whose URL lands on the next line is not a false
// positive. Prose paragraphs in the section are allowed and unchecked: a page
// honestly explaining its unsourced-hypothesis status in prose passes; a
// bullet NAMING a source with no URL is the always-wrong case. No non-empty
// requirement (a newborn page is legitimately thin), and no URL liveness
// probe (network in a check breaks offline determinism).
const URL = /https?:\/\//;

const rule = {
  id: 'product-wiki-sources',
  severity: 'blocking',
  doc: 'packs/product-wiki/README.md',
  description: 'Every Sources bullet carries its real URL',
  why: 'a named source without its URL is an uncited citation — unverifiable by the next pass and by review',

  run(ctx) {
    const out = [];
    for (const page of wikiPages(ctx.files)) {
      const text = ctx.read(page);
      if (text === null) continue;
      const section = sectionBody(text, 'sources');
      if (section === null) continue; // page-sections owns the missing heading
      for (let i = 0; i < section.length; i++) {
        if (!BULLET.test(section[i].text)) continue;
        let block = section[i].text;
        for (let j = i + 1; j < section.length && /^\s+\S/.test(section[j].text); j++) {
          block += ` ${section[j].text.trim()}`;
        }
        if (!URL.test(block)) {
          out.push(finding(rule, {
            file: page,
            line: section[i].line,
            what: `Sources bullet carries no URL: "${section[i].text.trim().slice(0, 80)}"`,
            fix: 'every listed source carries its real URL (a markdown link or a bare URL); an honestly-unsourced page explains its status in prose instead of listing URL-less sources',
          }));
        }
      }
    }
    return out;
  },
};

export default rule;
import { finding } from '../../engine/checks/helpers/findings.mjs';
import { wikiPages, sectionBody, BULLET, DATED, realDateUTC } from './lib.mjs';

// Growth-log discipline: every top-level bullet in the section leads with its
// run date (bold or plain — the invariant is dating, not typography), the date
// is a real calendar date, and a seeded page has at least one entry (a page
// with content and an empty log never recorded its seed). Indented
// continuation lines and prose paragraphs are ignored; the bullet/date grammar
// is lib.mjs's, shared with the freshness advisory so the two checks can never
// disagree about what an entry date is. Deliberately absent: ordering (a
// backdated correction is legitimate) and any wall-clock rule (staleness is
// the freshness advisory's job).
const FIX = 'lead every growth-log bullet with the run date, e.g. "- **2026-07-15** — what changed"; append the seed entry when the page is first committed';

const rule = {
  id: 'product-wiki-growth-log',
  severity: 'blocking',
  doc: 'packs/product-wiki/README.md',
  description: 'Every Growth log entry is a dated bullet (real YYYY-MM-DD), and a seeded page has at least one',
  why: 'undated or absent log entries break the audit trail and the freshness signal every other growth mechanism keys on',

  run(ctx) {
    const out = [];
    for (const page of wikiPages(ctx.files)) {
      const text = ctx.read(page);
      if (text === null) continue;
      const section = sectionBody(text, 'growth log');
      if (section === null) continue; // page-sections owns the missing heading
      let bullets = 0;
      for (const { line, text: t } of section) {
        if (!BULLET.test(t)) continue; // top-level bullets only
        bullets += 1;
        const m = DATED.exec(t);
        if (!m) {
          out.push(finding(rule, {
            file: page, line,
            what: `growth-log entry does not lead with its date: "${t.trim().slice(0, 80)}"`,
            fix: FIX,
          }));
          continue;
        }
        if (realDateUTC(+m[1], +m[2], +m[3]) === null) {
          out.push(finding(rule, {
            file: page, line,
            what: `growth-log entry "${m[1]}-${m[2]}-${m[3]}" is not a real calendar date`,
            fix: FIX,
          }));
        }
      }
      if (bullets === 0) {
        out.push(finding(rule, { file: page, what: 'growth log has no dated entries', fix: FIX }));
      }
    }
    return out;
  },
};

export default rule;
import { finding } from '../../engine/checks/helpers/findings.mjs';
import { wikiPages, sectionBody, firstSection, BULLET } from './lib.mjs';

// The reader's entry point: every wiki page OPENS with a short bulleted list of
// what the research actually found, so a human gets the page's understanding
// without reading it end to end (the body stays the research record). Four
// always-wrong shapes are checkable, and only those — WHICH insights lead is
// judgment, owned by the prose and the growth worker:
//   * the header sits below another section (it isn't a header then);
//   * it carries no bullets (an empty promise at the top of the page);
//   * it has grown into a second body (more than MAX bullets);
//   * a bullet is a paragraph rather than a line (over MAX_CHARS).
// Prose lines in the section are flagged for the same reason: the contract is a
// scannable list, not a summary paragraph. Indented continuation lines belong to
// the bullet above them (judged as one block, like a Sources citation), so a
// hard-wrapped insight is never a false positive. Presence of the heading itself
// is page-sections' finding — never double-reported here.
//
// MAX_CHARS is deliberately tight — roughly one line of prose. A header is worth
// having only if it is faster to read than the page, and the failure mode in
// practice is a bullet that keeps qualifying itself. The nuance the qualifier
// wanted belongs in the body; the header states the finding plainly and stops.
const MAX = 7;
const MAX_CHARS = 140;
const NAME = 'Key insights';
const FIX = `open the page with "## ${NAME}" — up to ${MAX} bullets, each one finding stated plainly in a line (max ${MAX_CHARS} characters), together enough for a reader to understand what the research found without reading the body`;

const rule = {
  id: 'product-wiki-key-insights',
  severity: 'blocking',
  doc: 'packs/product-wiki/README.md',
  description: 'Every wiki page opens with a succinct bulleted Key insights header',
  why: 'a research page whose findings can only be recovered by reading it end to end does not get read — the header is what makes a compiled wiki usable to a human',

  run(ctx) {
    const out = [];
    for (const page of wikiPages(ctx.files)) {
      const text = ctx.read(page);
      if (text === null) continue;
      const section = sectionBody(text, NAME);
      if (section === null) continue; // page-sections owns the missing heading

      const first = firstSection(text);
      if (first !== null && !new RegExp(`^${NAME}\\b`, 'i').test(first)) {
        out.push(finding(rule, {
          file: page,
          what: `the page opens with "## ${first}", not its "## ${NAME}" header`,
          fix: `move "## ${NAME}" above every other section — a header a reader reaches after the body is not a header`,
        }));
      }

      let bullets = 0;
      for (let i = 0; i < section.length; i++) {
        const { line, text: t } = section[i];
        if (!BULLET.test(t)) {
          // Blank lines and a bullet's own indented continuation lines are the
          // list's own shape; anything else is prose in a list-only section.
          if (t.trim() !== '' && !/^\s+\S/.test(t)) {
            out.push(finding(rule, {
              file: page, line,
              what: `prose in the ${NAME} header: "${t.trim().slice(0, 80)}"`,
              fix: `the header is a bulleted list only — make it a bullet or move it into the page body below the "## ${NAME}" section`,
            }));
          }
          continue;
        }
        bullets += 1;
        let block = t;
        for (let j = i + 1; j < section.length && /^\s+\S/.test(section[j].text); j++) {
          block += ` ${section[j].text.trim()}`;
        }
        if (block.trim().length > MAX_CHARS) {
          out.push(finding(rule, {
            file: page, line,
            what: `${NAME} bullet runs ${block.trim().length} characters (max ${MAX_CHARS}): "${t.trim().slice(0, 80)}…"`,
            fix: 'cut it to the finding in plain words — the qualifiers, the supporting detail and the citation all live in the page body',
          }));
        }
      }

      if (bullets === 0) {
        out.push(finding(rule, { file: page, what: `${NAME} header carries no bullets`, fix: FIX }));
      } else if (bullets > MAX) {
        out.push(finding(rule, {
          file: page,
          what: `${NAME} header carries ${bullets} bullets (max ${MAX}) — it has grown into a second body`,
          fix: `keep the ${MAX} that matter most; the rest is what the page body is for`,
        }));
      }
    }
    return out;
  },
};

export default rule;
import { finding } from '../../engine/checks/helpers/findings.mjs';
import { wikiPages, sectionBody, DATED, realDateUTC } from './lib.mjs';

// The staleness nag — ADVISORY by design, never blocking: it is time-driven
// and directional (it goes red with no change to the repo), which must never
// block a Stop or fail CI. It exists because it is the only in-repo observer
// for the real failure mode "the unattended growth channel silently stopped
// firing" — ~6 weekly cycles of silence earns a nag. Per-page (one active wiki
// must not mask starved siblings), gated on mode 'all' (a whole-repo
// assertion; the Stop hook and CI both run 'all', so coverage is unchanged).
//
// Only ENTRY dates count — the leading date of a top-level bullet, lib.mjs's
// DATED grammar shared with the growth-log check — never a date mentioned in
// an entry's body or the section's prose, which would silently reset the
// staleness clock this advisory exists to watch. Entry dates more than 2 days
// in the future are discarded so a typo'd future date can't mark a page fresh
// forever. Silence it with rules: {"product-wiki-freshness": "off"}.
const WINDOW_DAYS = 45;
const DAY = 86_400_000;

const rule = {
  id: 'product-wiki-freshness',
  severity: 'advisory',
  doc: 'packs/product-wiki/README.md',
  description: `A wiki page whose newest Growth log entry is older than ${WINDOW_DAYS} days needs a growth pass`,
  why: "a wiki that stopped growing silently stops being true — staleness must reach a human even when the unattended growth channel isn't firing",

  run(ctx) {
    if (ctx.mode !== 'all') return [];
    const out = [];
    const now = ctx.now ?? Date.now(); // ctx.now: injectable clock for tests / future core seam
    for (const page of wikiPages(ctx.files)) {
      const text = ctx.read(page);
      if (text === null) continue;
      const section = sectionBody(text, 'growth log');
      if (section === null) continue;
      const dates = [];
      for (const { text: t } of section) {
        const m = DATED.exec(t);
        if (!m) continue; // undated/malformed bullets are growth-log's territory
        const ts = realDateUTC(+m[1], +m[2], +m[3]);
        if (ts !== null && ts <= now + 2 * DAY) dates.push(ts);
      }
      if (!dates.length) continue;
      const newest = Math.max(...dates);
      const age = Math.floor((now - newest) / DAY);
      if (age > WINDOW_DAYS) {
        out.push(finding(rule, {
          file: page,
          what: `newest Growth log entry is ${age} days old (${new Date(newest).toISOString().slice(0, 10)}) — past the ${WINDOW_DAYS}-day freshness window`,
          fix: "run a product-wiki growth pass (in-session: \"grow the product wiki\"; method: the canon's packs/product-wiki/tasks/wiki-growth/task.md, mounted under .claudinite/ in consumers), or confirm this repo's scheduler workflow is wired and the wiki-growth task is on its schedule; silence via rules: {\"product-wiki-freshness\": \"off\"}",
        }));
      }
    }
    return out;
  },
};

export default rule;

