// Travel-time estimation between Fringe venues.
//
// Pure — no DOM, no fetch. Ported from the home site's js/app.js (the haversine
// `distanceKm` and the `TRAVEL_SPEEDS_KMH` table) so the planner estimates
// travel between two shows the same way the "Now" map does. The scheduling
// engine uses this to size the gap it requires between back-to-back shows at
// different venues, and the schedule graphic uses it to label the travel leg
// drawn between two shows less than an hour apart.

// The three ways the planner lets you get between venues. Short, stable keys —
// the UI maps them to labels/emoji (🚶 🚲 🚗). Matches the home site's three
// modes (there is no bus mode: we can't give honest headway-aware bus times).
export const TRAVEL_MODES = ["walk", "bike", "car"];

// Rough door-to-door speeds (km/h) used to turn crow-flies distance into a
// travel estimate.
export const TRAVEL_SPEED_KMH = {
  // Walking is dialled down to ~2/3 of a brisk 5 km/h — Edinburgh's closes,
  // hills, stairs and festival crowds make real walking slower than the map
  // distance suggests. (Same figure as js/app.js.)
  walk: (5 * 2) / 3, // ≈ 3.33 km/h
  bike: 15,
  // A car in the congested August city centre is only a little quicker than a
  // bike once you count one-way systems, closures and parking.
  car: 22,
};

export const DEFAULT_TRAVEL_MODE = "walk";

/** Normalize a coordinate given as {lat,lng} or [lat,lng] to [lat,lng], or
 *  null when either component is missing (unknown / online venue). */
function coordPair(c) {
  if (!c) return null;
  let lat, lng;
  if (Array.isArray(c)) {
    [lat, lng] = c;
  } else {
    lat = c.lat;
    lng = c.lng;
  }
  if (lat == null || lng == null || Number.isNaN(lat) || Number.isNaN(lng)) return null;
  return [Number(lat), Number(lng)];
}

/**
 * Great-circle distance in kilometres between two points (haversine). Accepts
 * either {lat,lng} objects or [lat,lng] pairs. Returns null if either point has
 * no usable coordinates.
 * @param {{lat:number,lng:number}|[number,number]} a
 * @param {{lat:number,lng:number}|[number,number]} b
 * @returns {number|null}
 */
export function distanceKm(a, b) {
  const pa = coordPair(a);
  const pb = coordPair(b);
  if (!pa || !pb) return null;
  const [lat1, lng1] = pa;
  const [lat2, lng2] = pb;
  const R = 6371;
  const toRad = (d) => (d * Math.PI) / 180;
=====AVAIL=====
// Port of the availability semantics in edfringe/extract.py (UNAVAILABLE_STATUSES,
// NON_TICKETED_STATUSES, and the `available` boolean around lines 26-45 & 131-134),
// plus small date/time helpers for the shows.json performance shape.
//
// Field-mapping note (Python model vs. the real shows.json data this runs against):
//   - Python's Performance carries `ticket_status` (from the raw event's
//     `ticketStatus`); shows.json instead uses the field name `status`. Same
//     values, different key — `isAvailable` below reads `perf.status`.
//   - Python's Performance has separate `start`/`end` ISO datetimes (end derived
//     server-side from `estimatedEndDateTime` or `duration`). shows.json only
//     gives `date` + `start` ("HH:MM"), no `end` — see `perfEndMinutes` /
//     `perfEndDate`, which derive it from the show's `duration` (minutes),
//     falling back to end === start when duration is absent, matching the
//     Python fallback of `end = start + timedelta(minutes=dur)` (dur may be None).

// A performance is bookable unless its status is one of these (or it's sold
// out). Denylist ported verbatim from extract.py's UNAVAILABLE_STATUSES so that
// offer statuses like TWO_FOR_ONE / PAY_WHAT_YOU_WANT stay available — they
// still sell tickets.
export const UNAVAILABLE_STATUSES = new Set([
  "SOLD_OUT", "SOLD OUT", "SOLDOUT", "OFF_SALE", "OFFSALE", "NOT_ON_SALE",
  "NOT_YET_ON_SALE", "COMING_SOON", "CANCELLED", "CANCELED", "UNAVAILABLE",
  "POSTPONED", "SUSPENDED",
  // No online allocation left — you'd have to contact the venue, so it can't
  // be added to the edfringe basket. Treated as unavailable for scheduling.
  "NO_ALLOCATION_CONTACT_VENUE",
]);

// Statuses where the show is attended for free with no ticket to buy.
// Attendable (so available), but the purchase step has nothing to add to the
// basket.
